      for (int r = 0; r <= 14; ++r) g.SetValue(c, r, 1);
    Dump("cross input", g);
    Dump("cross thinned", ZhangSuenThinning(g));
  }
  {
    BinaryGrid g = Make(30, 16);
    for (int r = 0; r <= 4; ++r)
      for (int c = 0; c <= 29; ++c) g.SetValue(c, r, 1);
