    BinaryGrid g = Make(30, 16);
    for (int r = 0; r <= 4; ++r)
      for (int c = 0; c <= 29; ++c) g.SetValue(c, r, 1);
    for (int r = 5; r <= 7; ++r) g.SetValue(15, r, 1);
    Dump("bristle3 thinned", ZhangSuenThinning(g));
