  {
    BinaryGrid g = Make(20, 20);
    for (int r = 0; r <= 4; ++r)
      for (int c = 0; c <= 19; ++c) g.SetValue(c, r, 1);
    for (int c = 0; c <= 4; ++c)
      for (int r = 0; r <= 19; ++r) g.SetValue(c, r, 1);
    Dump("L thinned", ZhangSuenThinning(g));
  }
  return 0;
}

