# Independent reference implementation of Zhang-Suen from classic pseudocode.
def neighbors(img, x, y):
    # P2..P9 clockwise from north; returns list
    h, w = len(img), len(img[0])
    def g(cx, cy):
        if 0 <= cx < w and 0 <= cy < h:
            return img[cy][cx]
        return 0
    return [
        g(x, y-1),   # P2
        g(x+1, y-1), # P3
        g(x+1, y),   # P4
        g(x+1, y+1), # P5
        g(x, y+1),   # P6
        g(x-1, y+1), # P7
        g(x-1, y),   # P8
        g(x-1, y-1), # P9
    ]

def thin(img):
    img = [row[:] for row in img]
    changed = True
    while changed:
        changed = False
        for step in (0, 1):
            remove = []
            h, w = len(img), len(img[0])
            for y in range(h):
                for x in range(w):
                    if not img[y][x]:
                        continue
                    n = neighbors(img, x, y)
                    B = sum(n)
                    if B < 2 or B > 6:
                        continue
                    A = sum(1 for i in range(8) if n[i] == 0 and n[(i+1) % 8] == 1)
                    if A != 1:
                        continue
                    if step == 0:
                        if n[0]*n[2]*n[4] == 0 and n[2]*n[4]*n[6] == 0:
                            remove.append((x, y))
                    else:
                        if n[0]*n[2]*n[6] == 0 and n[0]*n[4]*n[6] == 0:
                            remove.append((x, y))
            if remove:
                changed = True
                for (x, y) in remove:
                    img[y][x] = 0
    return img

def show(img, title):
    print("==", title)
    for row in img:
        print("".join("#" if v else "." for v in row))

