static void Dump(const char* title, const BinaryGrid& g) {
  printf("== %s (%ux%u) ==\n", title, g.width, g.height);
  for (uint32_t r = 0; r < g.height; ++r) {
    for (uint32_t c = 0; c < g.width; ++c) {
      putchar(g.GetValue((int)c, (int)r) ? '#' : '.');
    }
    putchar('\n');
  }
}

static BinaryGrid Make(uint32_t w, uint32_t h) {
  BinaryGrid g;
  g.width = w;
  g.height = h;
  g.data.assign((size_t)w * h, 0);
  return g;
}

int main() {
  {
    BinaryGrid g = Make(20, 5);
    for (int r = 0; r <= 4; ++r)
